void menu_img_upload_pad(uint32 layout)
{
    // Original MIPS selects neGcon images at 0 and standard pad images at 4
    uint32 first = (layout ^ 1) * 4;

    // Original 0x80044DC8..0x80044E58 refreshes four embedded paletted TIMs
    for (uint32 idx = 0; idx < 4; ++idx)
    {
        const MENU_PAD_IMAGE *img = &menu_pad_images[first + idx];
        PSX_RECT rect = img->img_rect;

        LoadImagePSX(&rect, (uint32 *)img->img_data);
        rect = img->clut;
        LoadImagePSX(&rect, (uint32 *)img->clut_data);
    }
}

sint32 menu_img_decode_startup(GpuTimImage *img)
{
    return gpu_decode_tim_body(menu_startup_tim, sizeof(menu_startup_tim), img);
}
